-- Global action history. Snapshots intentionally omit image bytes.
CREATE TABLE action_history (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 kind TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL,
 entity_id TEXT NOT NULL, entity_name TEXT NOT NULL,
 tournament_id TEXT, tournament_name TEXT, category_id TEXT, category_name TEXT,
 before_data TEXT CHECK(before_data IS NULL OR json_valid(before_data)),
 after_data TEXT CHECK(after_data IS NULL OR json_valid(after_data)),
 historical INTEGER NOT NULL DEFAULT 0 CHECK(historical IN (0,1))
);
CREATE INDEX history_time ON action_history(occurred_at DESC,id DESC);
CREATE INDEX history_kind ON action_history(kind,occurred_at DESC,id DESC);
CREATE INDEX history_tournament ON action_history(tournament_id,occurred_at DESC,id DESC);
CREATE INDEX history_category ON action_history(category_id,occurred_at DESC,id DESC);
CREATE TRIGGER history_no_update BEFORE UPDATE ON action_history BEGIN SELECT RAISE(ABORT,'Action history is immutable'); END;
CREATE TRIGGER history_no_delete BEFORE DELETE ON action_history BEGIN SELECT RAISE(ABORT,'Action history is immutable'); END;

INSERT INTO action_history(occurred_at,kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,after_data,historical) SELECT h.created_at,'draws','recorded','category_draws',h.id,'Žreb / Draw', (SELECT tournament_id FROM categories WHERE id=h.category_id),(SELECT name FROM tournaments WHERE id=(SELECT tournament_id FROM categories WHERE id=h.category_id)),h.category_id,(SELECT name FROM categories WHERE id=h.category_id),json_object('revision',revision,'payload',payload),1 FROM category_draws h ORDER BY h.created_at;

INSERT INTO action_history(occurred_at,kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,after_data,historical) SELECT h.recorded_at,'results','recorded','match_results',h.id,match_key, (SELECT tournament_id FROM categories WHERE id=(SELECT category_id FROM category_draws WHERE id=h.draw_id)),(SELECT name FROM tournaments WHERE id=(SELECT tournament_id FROM categories WHERE id=(SELECT category_id FROM category_draws WHERE id=h.draw_id))),(SELECT category_id FROM category_draws WHERE id=h.draw_id),(SELECT name FROM categories WHERE id=(SELECT category_id FROM category_draws WHERE id=h.draw_id)),json_object('match_key',h.match_key,'revision',h.revision,'payload',h.payload,'first_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(h.payload,'$.first')),'first_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(h.payload,'$.first'))),'second_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(h.payload,'$.second')),'second_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(h.payload,'$.second'))),'winner_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(h.payload,'$.winner')),'winner_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(h.payload,'$.winner')))),1 FROM match_results h ORDER BY h.recorded_at;

INSERT INTO action_history(occurred_at,kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,after_data,historical) SELECT h.created_at,'cash',h.kind,'cash_records',h.id,kind, (SELECT tournament_id FROM categories WHERE id=(SELECT category_id FROM entries WHERE id=h.entry_id)),(SELECT name FROM tournaments WHERE id=(SELECT tournament_id FROM categories WHERE id=(SELECT category_id FROM entries WHERE id=h.entry_id))),(SELECT category_id FROM entries WHERE id=h.entry_id),(SELECT name FROM categories WHERE id=(SELECT category_id FROM entries WHERE id=h.entry_id)),json_object('kind',kind,'amount_minor',amount_minor,'note',note),1 FROM cash_records h ORDER BY h.created_at;

INSERT INTO action_history(occurred_at,kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,after_data,historical) SELECT h.recorded_at,'completion',CASE WHEN json_extract(h.payload,'$.completion.completed_at') IS NULL THEN 'reopened' ELSE 'completed' END,'completion_history',h.entity_id,'Završetak / Completion', CASE WHEN h.entity_kind='tournament' THEN h.entity_id ELSE (SELECT tournament_id FROM categories WHERE id=h.entity_id) END,(SELECT name FROM tournaments WHERE id=CASE WHEN h.entity_kind='tournament' THEN h.entity_id ELSE (SELECT tournament_id FROM categories WHERE id=h.entity_id) END),CASE WHEN h.entity_kind='category' THEN h.entity_id ELSE NULL END,(SELECT name FROM categories WHERE id=CASE WHEN h.entity_kind='category' THEN h.entity_id ELSE NULL END),json_object('revision',revision,'payload',payload),1 FROM completion_history h ORDER BY h.recorded_at;

INSERT INTO action_history(occurred_at,kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,after_data,historical) SELECT h.deleted_at,'trash','recorded','tournament_trash',h.tournament_id,'Korpa / Trash', h.tournament_id,(SELECT name FROM tournaments WHERE id=h.tournament_id),NULL,(SELECT name FROM categories WHERE id=NULL),NULL,1 FROM tournament_trash h ORDER BY h.deleted_at;

CREATE TRIGGER history_tournaments_insert AFTER INSERT ON tournaments
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('tournaments','created','tournaments',NEW.id,NEW.name,NEW.id,NEW.name,NULL,(SELECT name FROM categories WHERE id=NULL),NULL,json_object('name',NEW.name)); END;

CREATE TRIGGER history_tournaments_update AFTER UPDATE ON tournaments WHEN OLD.name IS NOT NEW.name
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('tournaments','updated','tournaments',NEW.id,NEW.name,NEW.id,NEW.name,NULL,(SELECT name FROM categories WHERE id=NULL),json_object('name',OLD.name),json_object('name',NEW.name)); END;

CREATE TRIGGER history_tournaments_delete AFTER DELETE ON tournaments
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('tournaments','deleted','tournaments',OLD.id,OLD.name,OLD.id,OLD.name,NULL,(SELECT name FROM categories WHERE id=NULL),json_object('name',OLD.name),NULL); END;

CREATE TRIGGER history_tournament_cover AFTER UPDATE OF cover ON tournaments WHEN OLD.cover IS NOT NEW.cover BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,before_data,after_data) VALUES('tournaments','image_changed','tournaments',NEW.id,NEW.name,NEW.id,NEW.name,json_object('has_image',OLD.cover IS NOT NULL),json_object('has_image',NEW.cover IS NOT NULL)); END;

CREATE TRIGGER history_categories_insert AFTER INSERT ON categories
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('categories','created','categories',NEW.id,NEW.name,NEW.tournament_id,(SELECT name FROM tournaments WHERE id=NEW.tournament_id),NEW.id,NEW.name,NULL,json_object('name',NEW.name,'discipline',NEW.discipline,'format',NEW.format,'fee_minor',NEW.fee_minor,'archived',NEW.archived)); END;

CREATE TRIGGER history_categories_update AFTER UPDATE ON categories WHEN OLD.name IS NOT NEW.name OR OLD.discipline IS NOT NEW.discipline OR OLD.format IS NOT NEW.format OR OLD.fee_minor IS NOT NEW.fee_minor OR OLD.archived IS NOT NEW.archived
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('categories',CASE WHEN OLD.archived IS NOT NEW.archived THEN CASE WHEN NEW.archived=1 THEN 'archived' ELSE 'restored' END ELSE 'updated' END,'categories',NEW.id,NEW.name,NEW.tournament_id,(SELECT name FROM tournaments WHERE id=NEW.tournament_id),NEW.id,NEW.name,json_object('name',OLD.name,'discipline',OLD.discipline,'format',OLD.format,'fee_minor',OLD.fee_minor,'archived',OLD.archived),json_object('name',NEW.name,'discipline',NEW.discipline,'format',NEW.format,'fee_minor',NEW.fee_minor,'archived',NEW.archived)); END;

CREATE TRIGGER history_categories_delete AFTER DELETE ON categories
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('categories','deleted','categories',OLD.id,OLD.name,OLD.tournament_id,(SELECT name FROM tournaments WHERE id=OLD.tournament_id),OLD.id,OLD.name,json_object('name',OLD.name,'discipline',OLD.discipline,'format',OLD.format,'fee_minor',OLD.fee_minor,'archived',OLD.archived),NULL); END;

