CREATE TRIGGER history_category_draws_insert AFTER INSERT ON category_draws
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('draws','created','category_draws',NEW.id,'Žreb / Draw',(SELECT tournament_id FROM categories WHERE id=NEW.category_id),(SELECT name FROM tournaments WHERE id=(SELECT tournament_id FROM categories WHERE id=NEW.category_id)),NEW.category_id,(SELECT name FROM categories WHERE id=NEW.category_id),(SELECT json_object('revision',d.revision,'payload',d.payload) FROM category_draws d WHERE d.category_id=NEW.category_id AND d.revision<NEW.revision ORDER BY d.revision DESC LIMIT 1),json_object('revision',NEW.revision,'payload',NEW.payload)); END;

CREATE TRIGGER history_match_results_insert AFTER INSERT ON match_results
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('results',CASE WHEN NEW.payload='null' THEN 'invalidated' WHEN NEW.revision>1 THEN 'corrected' ELSE 'recorded' END,'match_results',NEW.id,NEW.match_key,(SELECT tournament_id FROM categories WHERE id=(SELECT category_id FROM category_draws WHERE id=NEW.draw_id)),(SELECT name FROM tournaments WHERE id=(SELECT tournament_id FROM categories WHERE id=(SELECT category_id FROM category_draws WHERE id=NEW.draw_id))),(SELECT category_id FROM category_draws WHERE id=NEW.draw_id),(SELECT name FROM categories WHERE id=(SELECT category_id FROM category_draws WHERE id=NEW.draw_id)),(SELECT json_object('match_key',m.match_key,'revision',m.revision,'payload',m.payload,'first_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(m.payload,'$.first')),'first_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(m.payload,'$.first'))),'second_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(m.payload,'$.second')),'second_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(m.payload,'$.second'))),'winner_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(m.payload,'$.winner')),'winner_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(m.payload,'$.winner')))) FROM match_results m WHERE m.draw_id=NEW.draw_id AND m.match_key=NEW.match_key AND m.revision<NEW.revision ORDER BY m.revision DESC LIMIT 1),json_object('match_key',NEW.match_key,'revision',NEW.revision,'payload',NEW.payload,'first_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(NEW.payload,'$.first')),'first_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(NEW.payload,'$.first'))),'second_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(NEW.payload,'$.second')),'second_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(NEW.payload,'$.second'))),'winner_name',(SELECT group_concat(name_snapshot,' / ') FROM entry_members WHERE entry_id=json_extract(NEW.payload,'$.winner')),'winner_members',json((SELECT json_group_array(json_object('name',name_snapshot,'club',club_snapshot)) FROM entry_members WHERE entry_id=json_extract(NEW.payload,'$.winner'))))); END;

