BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('tables','updated','match_assignments',NEW.draw_id,NEW.match_key,NEW.tournament_id,(SELECT name FROM tournaments WHERE id=NEW.tournament_id),(SELECT category_id FROM category_draws WHERE id=NEW.draw_id),(SELECT name FROM categories WHERE id=(SELECT category_id FROM category_draws WHERE id=NEW.draw_id)),json_object('match_key',OLD.match_key,'table_number',OLD.table_number,'status',OLD.status,'started_at',OLD.started_at),json_object('match_key',NEW.match_key,'table_number',NEW.table_number,'status',NEW.status,'started_at',NEW.started_at)); END;

