CREATE TRIGGER history_completion_history_insert AFTER INSERT ON completion_history
BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('completion',CASE WHEN json_extract(NEW.payload,'$.completion.completed_at') IS NULL THEN 'reopened' ELSE 'completed' END,'completion_history',NEW.entity_id,COALESCE((SELECT name FROM categories WHERE id=NEW.entity_id),(SELECT name FROM tournaments WHERE id=NEW.entity_id)),CASE WHEN NEW.entity_kind='tournament' THEN NEW.entity_id ELSE (SELECT tournament_id FROM categories WHERE id=NEW.entity_id) END,(SELECT name FROM tournaments WHERE id=CASE WHEN NEW.entity_kind='tournament' THEN NEW.entity_id ELSE (SELECT tournament_id FROM categories WHERE id=NEW.entity_id) END),CASE WHEN NEW.entity_kind='category' THEN NEW.entity_id ELSE NULL END,(SELECT name FROM categories WHERE id=CASE WHEN NEW.entity_kind='category' THEN NEW.entity_id ELSE NULL END),(SELECT json_object('entity_kind',h.entity_kind,'revision',h.revision,'payload',h.payload) FROM completion_history h WHERE h.entity_kind=NEW.entity_kind AND h.entity_id=NEW.entity_id AND h.revision<NEW.revision ORDER BY h.revision DESC LIMIT 1),json_object('entity_kind',NEW.entity_kind,'revision',NEW.revision,'payload',NEW.payload)); END;

