BEGIN INSERT INTO action_history(kind,action,entity_type,entity_id,entity_name,tournament_id,tournament_name,category_id,category_name,before_data,after_data) VALUES('trash','restored','tournament_trash',OLD.tournament_id,(SELECT name FROM tournaments WHERE id=OLD.tournament_id),OLD.tournament_id,(SELECT name FROM tournaments WHERE id=OLD.tournament_id),NULL,(SELECT name FROM categories WHERE id=NULL),json_object(),NULL); END;

